class Solution {
public:
    bool canConvert(string str1, string str2) {
        if (str1 == str2) return true;
        vector<int> mapping(26, -1);
        for (int i = 0; i < (int)str1.size(); ++i) {
            int u = str1[i] - 'a', v = str2[i] - 'a';
            if (mapping[u] != -1 && mapping[u] != v) return false;
            mapping[u] = v;
        }
        unordered_set<char> unique_target(str2.begin(), str2.end());
        return unique_target.size() < 26;
    }
};

import java.util.*;

class Solution {
    public boolean canConvert(String str1, String str2) {
        if (str1.equals(str2)) return true;
        int[] mapping = new int[26];
        Arrays.fill(mapping, -1);
        for (int i = 0; i < str1.length(); i++) {
            int u = str1.charAt(i) - 'a', v = str2.charAt(i) - 'a';
            if (mapping[u] != -1 && mapping[u] != v) return false;
            mapping[u] = v;
        }
        Set<Character> unique = new HashSet<>();
        for (char c : str2.toCharArray()) unique.add(c);
        return unique.size() < 26;
    }
}

var canConvert = function(str1, str2) {
    if (str1 === str2) return true;
    const mapping = new Map();
    for (let i = 0; i < str1.length; i++) {
        const c1 = str1[i], c2 = str2[i];
        if (mapping.has(c1) && mapping.get(c1) !== c2) return false;
        mapping.set(c1, c2);
    }
    const unique = new Set(str2);
    return unique.size < 26;
};
